class PopFromEmptyStack(Exception):
    """Stack is empty, cannot pop from it!"""
    def __init__(self):
        """Basic initialization."""
        super(PopFromEmptyStack, self).__init__("Stack is empty, cannot pop from it!")


class TopOnEmptyStack(Exception):
    """Stack is empty, cannot get top item!"""
    def __init__(self):
        """Basic initialization."""
        super(TopOnEmptyStack, self).__init__("Stack is empty, cannot get top item!")


class Stack:
    """Handling of stack."""
    def __init__(self):
        """Basic initialization."""
        self.container = []

    def is_empty(self):
        """Check if stack is empty."""
        return self.size() == 0

    def top(self):
        """Return item from top of stack."""
        if self.is_empty():
            raise TopOnEmptyStack()
        return self.container[-1]

    def push(self, item):
        """Push item to stack."""
        self.container.append(item)

    def pop(self):
        """Pop item from top of stack and return it to caller."""
        if self.is_empty():
            raise PopFromEmptyStack()
        return self.container.pop()

    def size(self):
        """Return current size of stack."""
        return len(self.container)
